// Scene sprite data: the LPC layer atlas (hero + crewmate), action backdrops and the equipment -> layer mapping.
// Atlas, backdrops and boss portraits are generated by scripts/art/build-*.py (see art/credits-scene.md).
import heroUrl from './art/hero.png?url';
import heroMan from './art/hero.json';
import backdropUrl from './art/backdrops.png?url';
import backdropMan from './art/backdrops.json';
import foesUrl from './art/foes.png?url';
import foesMan from './art/foes.json';

export type AnimName = 'idle' | 'slash' | 'cast' | 'shoot' | 'fish';
interface LayerRect { x: number; y: number; w: number; h: number; ox: number; oy: number }
interface Manifest { anims: Record<AnimName, { frames: number; fps: number }>; layers: Record<string, Partial<Record<AnimName, LayerRect>>>; top: Record<string, number> }
export const MAN = heroMan as unknown as Manifest;
export const BD = backdropMan as { w: number; h: number; ground: number; names: string[] };

/** Native scene height. 64 (was 52): the 49px LPC frame needs the headroom; shown at 3x = 192 css px. */
export const SCENE_H = BD.h;
/** Feet line inside the scene. */
export const FEET_Y = SCENE_H - 6;

function load(url: string): Promise<HTMLImageElement> {
  return new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = url; });
}
let pending: Promise<{ atlas: HTMLImageElement; backdrops: HTMLImageElement; foes: HTMLImageElement }> | null = null;
export function loadSceneArt() { return (pending ??= Promise.all([load(heroUrl), load(backdropUrl), load(foesUrl)]).then(([atlas, backdrops, foes]) => ({ atlas, backdrops, foes }))); }

/** Foe sprite row for a combat action (16px, 4 idle frames, facing left); null when the action is not a fight. */
export const FOES = foesMan as { map: Record<string, number>; default: number; frames: number; size: number };
export const foeRow = (actionId: string | null, kind: string | null): number | null => (kind === 'combat' ? (actionId ? FOES.map[actionId] : undefined) ?? FOES.default : null);

// ---------------------------------------------------------------- actions -> backdrop / animation
const BACKDROP_BY_SKILL: Record<string, string> = {
  mining: 'mine', woodcutting: 'forest', herbalism: 'field', fishing: 'river', smelting: 'forge', smithing: 'forge',
  carpentry: 'workbench', tanning: 'workbench', weaving: 'workbench', woodworking: 'workbench', leatherworking: 'workbench',
  tailoring: 'workbench', jewelcrafting: 'workbench', alchemy: 'alchemy', cooking: 'kitchen',
  guardian: 'combat', mender: 'combat', striker: 'combat',
};
export const backdropFor = (skill: string | null) => (skill && BACKDROP_BY_SKILL[skill]) || 'yard';
export const backdropRow = (name: string) => Math.max(0, BD.names.indexOf(name));

/** Tool carried while working a skill (otherwise a hands-only gesture or idle). */
const TOOL_BY_SKILL: Record<string, ToolKind> = {
  mining: 'pickaxe', woodcutting: 'axe', fishing: 'rod',
  smithing: 'hammer', smelting: 'hammer', carpentry: 'hammer', woodworking: 'hammer', leatherworking: 'hammer', jewelcrafting: 'hammer',
};
/** Hands-only work (arms reach and move: the spellcast pose without a staff): gathering herbs, cloth, kitchen and alchemy bench. */
const GESTURE = new Set(['herbalism', 'tanning', 'weaving', 'tailoring', 'cooking', 'alchemy']);
const COMBAT = new Set(['guardian', 'mender', 'striker']);

// ---------------------------------------------------------------- equipment -> layers
/** The 12 weapon types of the gear data model; each has its own worn look (atlas layers `w_<type>_<material>_bg|fg`, built by scripts/art/build-hero.py).
 *  Closest LPC layer, recoloured by material: spear = rapier, halberd = pickaxe head, warhammer = smith's hammer, scepter = club (brass), axe = hand axe. */
export type WeaponType = 'sword' | 'axe' | 'dagger' | 'spear' | 'bow' | 'greatsword' | 'mace' | 'warhammer' | 'halberd' | 'wand' | 'scepter' | 'staff';
type ToolKind = 'pickaxe' | 'axe' | 'hammer' | 'rod';
export function weaponKind(id: string | null): WeaponType | null {
  if (!id || /parrying/.test(id)) return null;
  if (/greatsword/.test(id)) return 'greatsword';
  if (/dagger/.test(id)) return 'dagger';
  if (/spear/.test(id)) return 'spear';
  if (/halberd/.test(id)) return 'halberd';
  if (/warhammer|maul|hammer/.test(id)) return 'warhammer';
  if (/mace/.test(id)) return 'mace';
  if (/scepter/.test(id)) return 'scepter';
  if (/wand/.test(id)) return 'wand';
  if (/staff/.test(id)) return 'staff';
  if (/bow/.test(id)) return 'bow';
  if (/axe/.test(id)) return 'axe';
  return 'sword';
}
const WOODEN: WeaponType[] = ['bow', 'staff', 'wand'];
const SWORD_MATS = ['bronze', 'bronze', 'iron', 'steel', 'gold'];
/** Material look of a weapon by tier: wood (pine, oak, yew) for bow, staff, wand; metal (bronze, iron, steel) for the rest. T4 and up keep the T3 look. */
const matOf = (t: WeaponType, tier: number) => {
  const i = Math.min(3, Math.max(1, tier || 1)) - 1;
  return (WOODEN.includes(t) ? ['pine', 'oak', 'yew'] : ['bronze', 'iron', 'steel'])[i];
};

export interface Gear { itemId: string | null; tier: number; role: string }
export interface Equipped { weapon: Gear | null; head: Gear | null; chest: Gear | null; legs: Gear | null; offhand?: Gear | null }
/** Offhand worn look: shields by tier (buckler, kite, tower, aegis), the tome as a leather-bound board, the parrying dagger held back on the off side. */
const SHIELD_BY_TIER = ['sh_buckler', 'sh_buckler', 'sh_kite', 'sh_tower', 'sh_aegis'];
export function offhandLook(g: Gear | null | undefined): { bg: string[]; fg: string[]; shield: boolean } | null {
  const id = g?.itemId ?? '';
  if (!g || !id) return null;
  const tier = Math.min(4, Math.max(1, g.tier || 1));
  if (/shield|buckler|aegis/.test(id)) { const k = SHIELD_BY_TIER[tier]; return { bg: [`${k}_bg`], fg: [`${k}_fg`], shield: true }; }
  if (/tome/.test(id)) return { bg: ['sh_tome_bg'], fg: ['sh_tome_fg'], shield: true };
  if (/parrying/.test(id)) return { bg: [`w_pd_${matOf('dagger', tier)}_bg`, `w_pd_${matOf('dagger', tier)}_fg`], fg: [], shield: false };
  return null;
}
/** `hold`: a fixed frame for a calm standing pose (idle with a weapon in hand: only the action anims carry weapon layers). */
export interface Look { back: string[]; front: string[]; anim: AnimName; backdrop: string; key: string; hold?: number }
const HOLD: Record<AnimName, number> = { idle: 0, slash: 0, cast: 0, shoot: 3, fish: 0 };
/** Frame to draw for `look` at time `t` (ms). Honours `hold`; `still` (reduced motion) shows frame 0 or the hold frame. */
export function lookFrame(look: Look, t: number, still = false, phase = 0): number {
  if (look.hold != null) return look.hold;
  const a = MAN.anims[look.anim];
  return still ? 0 : Math.floor((t + phase) / 1000 * a.fps) % a.frames;
}

function bodyLayers(eq: Equipped, crew: boolean): { under: string[]; over: string[] } {
  if (crew) return { under: ['c_body', 'c_head', 'c_boots', 'c_pants', 'c_shirt', 'c_hair'], over: [] };
  const chest = eq.chest, legs = eq.legs, head = eq.head;
  const cid = chest?.itemId ?? '';
  const torso = !chest ? 'c_shirt'
    : /chain/.test(cid) ? 't_chain'
    : chest.role === 'striker' ? 't_leather'
    : chest.role === 'mender' ? 't_cloth' : 't_plate';
  const pants = legs && legs.role === 'guardian' ? 'legs_plate' : 'pants';
  const hid = head?.itemId ?? '';
  const helm = !head ? null
    : /hood|cowl/.test(hid) || head.role === 'mender' ? 'h_hood'
    : head.role === 'guardian' ? (head.tier <= 2 ? 'h_mail' : 'h_kettle') : 'h_cap';
  const showHair = !helm || helm === 'h_cap';
  return { under: ['body', 'head', 'boots', pants, torso, ...(showHair ? ['hair'] : [])], over: helm ? [helm] : [] };
}

function toolLayers(tool: ToolKind): { anim: AnimName; bg: string[]; fg: string[] } {
  return tool === 'rod' ? { anim: 'fish', bg: ['rod_bg'], fg: ['rod_fg'] } : { anim: 'slash', bg: [`${tool}_bg`], fg: [`${tool}_fg`] };
}
function weaponLayers(kind: WeaponType | null, w: Gear | null): { anim: AnimName; bg: string[]; fg: string[] } | null {
  if (!kind) return null;
  if (kind === 'sword') { const m = SWORD_MATS[Math.min(4, Math.max(1, w?.tier ?? 1))]; return { anim: 'slash', bg: [`sword_${m}_bg`], fg: [`sword_${m}_fg`] }; }
  const m = matOf(kind, w?.tier ?? 1);
  const anim: AnimName = kind === 'staff' ? 'cast' : kind === 'bow' ? 'shoot' : 'slash';
  return { anim, bg: [`w_${kind}_${m}_bg`], fg: [`w_${kind}_${m}_fg`] };
}

/** Layer draw lists for one figure working `skill`. `crew` = the crewmate palette (always plain work clothes). */
export function figure(skill: string | null, active: boolean, eq: Equipped, crew: boolean): Look {
  const { under, over } = bodyLayers(eq, crew);
  let anim: AnimName = 'idle';
  let bg: string[] = [], fg: string[] = [];
  if (active && skill) {
    const tool = TOOL_BY_SKILL[skill];
    const wk = crew ? null : weaponKind(eq.weapon?.itemId ?? null);
    const w = tool ? toolLayers(tool) : COMBAT.has(skill) && !crew ? weaponLayers(wk, eq.weapon) : null;
    if (COMBAT.has(skill) && !crew && !w) anim = 'slash';       // bare-handed
    else if (!w && GESTURE.has(skill)) anim = 'cast';
    if (w) { anim = w.anim; bg = w.bg; fg = w.fg; }
  }
  // Idle with a weapon equipped: show it, held still (worn gear should be visible everywhere).
  let hold: number | undefined;
  if (!(active && skill) && !crew && eq.weapon) {
    const w = weaponLayers(weaponKind(eq.weapon.itemId), eq.weapon);
    if (w) { anim = w.anim; bg = w.bg; fg = w.fg; hold = HOLD[w.anim]; }
  }
  // Offhand (shield, tome, parrying dagger): drawn in every animation that has shield art (slash, cast, shoot, fish). Offhand-only idle holds slash frame 0.
  const oh = crew ? null : offhandLook(eq.offhand);
  if (oh) {
    if (oh.shield && anim === 'idle') { anim = 'slash'; hold = HOLD.slash; }
    if (!oh.shield && anim !== 'slash') { /* the parrying dagger only has a slash pose: leave it out of other poses */ } else { bg = [...oh.bg, ...bg]; fg = [...oh.fg, ...fg]; }
  }
  const back = bg, front = fg;
  return { back, front: [...under, ...over, ...front], anim, backdrop: backdropFor(active ? skill : null), hold, key: [crew ? 'c' : 'h', anim, hold ?? '', ...bg, ...under, ...over, ...front].join(',') };
}

/** Frame index in each animation where the tool actually lands / the spell or arrow is released (the "hit"). */
export const HIT_FRAME: Record<AnimName, number | null> = { idle: null, slash: 2, cast: 5, shoot: 9, fish: 5 };
/** Absolute (rAF clock, ms) times of the hits of `anim` that fall in (from, to]. Frames advance on the same clock the scene paints with. */
export function hitsBetween(anim: AnimName, from: number, to: number, phase = 0): number[] {
  const h = HIT_FRAME[anim]; const a = MAN.anims[anim];
  if (h == null || !a) return [];
  const cycle = (a.frames / a.fps) * 1000, at = (h / a.fps) * 1000;
  const out: number[] = [];
  for (let k = Math.max(0, Math.floor((from - phase - at) / cycle)); ; k++) {
    const t = k * cycle + at + phase;
    if (t > to) break;
    if (t > from) out.push(t);
  }
  return out;
}
export const cycleMs = (anim: AnimName) => (MAN.anims[anim].frames / MAN.anims[anim].fps) * 1000;
